const paths={
'Web Development':{icon:'⌘',desc:'Bring useful ideas to life on the web.',skill:'HTML foundations',lesson:'HTML gives a web page its structure. A heading introduces a section, a paragraph holds text, and a button performs an action. Choose elements by their purpose so people and assistive technologies can understand your page.',question:'Which element should you use for an action such as submitting a form?',answers:['A paragraph','A button','A heading'],correct:1,explain:'A button represents an action and supports keyboard interaction. A paragraph is for text and a heading introduces content.',project:'Build a personal profile page',steps:['HTML foundations','Responsive layouts','JavaScript interactions','Portfolio project','Application preparation']},
'Cybersecurity':{icon:'◈',desc:'Learn to understand systems and protect people.',skill:'Security foundations',lesson:'Phishing messages try to make you reveal information or take an unsafe action. A familiar logo does not prove a message is genuine. Verify unusual requests using a trusted contact method you already know. Practise only in authorised learning environments.',question:'An urgent email asks for your college password. What is the best next action?',answers:['Reply with the password','Trust the college logo','Verify through the official college portal or known support contact'],correct:2,explain:'Independent verification avoids relying on links or contact details supplied in the suspicious message. Never send your password in a reply.',project:'Create a phishing awareness guide',steps:['Security foundations','Networks and Linux','Guided defensive labs','Investigation project','Application preparation']},
'Data Analytics':{icon:'▥',desc:'Turn questions and data into clear explanations.',skill:'Data foundations',lesson:'Before analysing data, understand what each row represents and check missing values, units, and repeated records. A missing value is not automatically zero. Document assumptions so others can understand your conclusions.',question:'A sales amount is missing. What should you do first?',answers:['Replace it with zero automatically','Investigate why it is missing and document your approach','Delete the entire dataset'],correct:1,explain:'Investigating missing values helps avoid misleading results. The appropriate treatment depends on the context and your analysis.',project:'Explore a small public dataset',steps:['Data foundations','Spreadsheets and SQL','Analysis and charts','Insight report','Application preparation']},
'Accounting':{icon:'▤',desc:'Build confidence with business records and numbers.',skill:'Accounting foundations',lesson:'The accounting equation is Assets = Liabilities + Equity. If a business borrows money and receives it in its bank account, both its assets and liabilities increase. Revenue and cash received are not always the same thing.',question:'A business receives a bank loan. Which two categories increase?',answers:['Assets and liabilities','Revenue and expenses','Only equity'],correct:0,explain:'Cash is an asset and the loan is a liability. Receiving a loan does not itself create sales revenue.',project:'Prepare a sample transaction journal',steps:['Accounting foundations','Transaction practice','Spreadsheet modelling','Financial report','Application preparation']},
'Marketing':{icon:'◎',desc:'Understand people and communicate useful ideas.',skill:'Customer research',lesson:'Good customer research starts with understanding a person’s experience. Open questions invite specific stories. Asking about a recent real experience is often more useful than asking someone to agree with your proposed solution.',question:'Which question is most useful for exploring a customer problem?',answers:['You love our idea, right?','Tell me about the last time you faced this problem','Will everyone buy our product?'],correct:1,explain:'A recent example reveals context and behaviour without pushing the person toward agreement.',project:'Create a customer interview plan',steps:['Customer research','Audience and positioning','Campaign basics','Campaign portfolio','Application preparation']},
'Mechanical Design':{icon:'⚙',desc:'Explore how useful physical products take shape.',skill:'Design requirements',lesson:'Before modelling a component, define its function, loads, dimensions, material constraints, and operating conditions. A visually attractive model alone does not prove a part is suitable. Assumptions need to be documented and checked.',question:'What should come before detailed CAD modelling?',answers:['Choose a colour','Define the function and constraints','Prepare the final presentation'],correct:1,explain:'Clear requirements guide the design and the checks needed to evaluate it.',project:'Write a component design brief',steps:['Design requirements','Engineering drawings','CAD practice','Design project','Application preparation']},
'UI/UX Design':{icon:'◇',desc:'Make everyday digital experiences easier to use.',skill:'Accessible interaction',lesson:'An accessible interface gives controls clear labels, supports keyboard use, and communicates information through more than colour. A person should be able to understand an error and know how to fix it.',question:'How should a form explain an invalid email address?',answers:['Only change the border to red','Show a clear message next to the field and associate it with the input','Remove the field'],correct:1,explain:'A clear associated message explains what needs fixing without relying only on colour.',project:'Redesign a college registration form',steps:['Accessible interaction','User research','Wireframes and prototypes','Design case study','Application preparation']}}
const $=s=>document.querySelector(s);let saved={};try{saved=JSON.parse(localStorage.getItem('nextstep-v1')||'{}')}catch{}const state={name:'Alex',course:'B.Tech / B.E. Computer Science',year:'Second year',path:'Web Development',language:'JavaScript',completed:{},projects:[],...saved};if(!paths[state.path])state.path='Web Development';let page='dashboard';const persist=()=>{try{localStorage.setItem('nextstep-v1',JSON.stringify(state))}catch{toast('Storage is unavailable. Progress lasts for this session.')}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const done=()=>!!state.completed[state.path];const count=()=>Object.keys(state.completed).length;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function title(h,p){return `<div class="heading"><div><div class="eyebrow">YOUR FUTURE, IN PROGRESS</div><h1>${h}</h1><p>${p}</p></div></div>`}function go(p){page=p;render();window.scrollTo(0,0)}function render(){const p=paths[state.path];$('nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent='My workspace / '+({dashboard:'Dashboard',roadmap:'My roadmap',explore:'Explore paths',projects:'My projects',opportunities:'Opportunities',resume:'Resume studio'}[page]);$('#profile').innerHTML=`<b>${esc(state.name[0]||'S')}</b><span>${esc(state.name)}<small>Personalise your journey ⚙</small></span>`;let html='';
if(page==='dashboard')html=`<div class="heading"><div><div class="eyebrow">LET’S MAKE TODAY COUNT</div><h1>A little progress. A bigger future, ${esc(state.name)}.</h1><p>Your journey is your own. Let’s take the next step.</p></div><div class="streak"><span>🔥</span><div><strong>${count()?'Learning started':'A fresh start'}</strong><small>${count()?'Keep your curiosity going':'Your first mission awaits'}</small></div></div></div><section class="hero"><div class="hero-copy"><span class="pill">YOUR NEXT SMALL WIN</span><h2>${done()?'You’ve taken your first step. Keep building.':'Big ambitions start with a small mission.'}</h2><p>${done()?'Put your new knowledge into practice with a project of your own.':`Explore ${esc(p.skill.toLowerCase())}, try a knowledge check, and start moving forward.`}</p><button class="primary" data-action="${done()?'projects':'lesson'}">${done()?'Start a project':'Start today’s mission'} <span>↗</span></button> <span style="font-size:10px;color:#7d896e;margin-left:10px">${done()?'Learn by doing':'◷ About 5 minutes'}</span></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="spark">✦</span><div class="step s1">⌘</div><div class="step s2">✓</div><div class="step s3">⚑</div></div></section><div class="stats"><div class="stat"><span class="stat-icon">⌁</span><div><strong>${done()?1:0}<span style="font-size:12px;color:#a0aa99"> / 5</span></strong><small>Journey milestones</small></div></div><div class="stat"><span class="stat-icon">✦</span><div><strong>${count()*50}</strong><small>Learning XP</small></div></div><div class="stat"><span class="stat-icon">▧</span><div><strong>${state.projects.length}</strong><small>Projects in progress</small></div></div><div class="stat"><span class="stat-icon">◈</span><div><strong>${count()}</strong><small>Knowledge checks passed</small></div></div></div><div class="columns"><section><div class="section-head"><h2>Your learning journey</h2><button class="text-button" data-action="roadmap">View roadmap ↗</button></div><div class="card"><div class="path-top"><span class="tag">${esc(state.year.toUpperCase())}</span><span style="color:#93a084">${p.icon}</span></div><h3>${esc(state.path)}</h3><p>${p.desc}</p><div class="progress"><div style="width:${done()?20:0}%"></div></div><div class="progress-label"><span>${done()?'1 milestone completed':'Your starting line'}</span><span>${done()?20:0}%</span></div>${p.steps.slice(0,3).map((s,i)=>`<div class="milestone"><span class="node ${i===0?'current':''}">${i===0?(done()?'✓':'1'):'◇'}</span><div><strong>${s}</strong><small>${i===0?(done()?'Introductory check completed':'Ready when you are'):'Content in preparation'}</small></div>${i===0?'<button data-action="lesson">'+(done()?'Review':'Start →')+'</button>':''}</div>`).join('')}</div></section><section><div class="section-head"><h2>A little perspective</h2><span>✧</span></div><div class="card note-card"><div class="mini-label">A NOTE FOR YOUR JOURNEY</div><h3>You don’t need to have it all figured out.</h3><p>Try something. Ask questions. Make mistakes. Every small step teaches you something about where you want to go.</p><button class="text-button" data-action="explore">Find a path that feels like you ↗</button></div><div class="below"><div class="section-head"><h2>Build something meaningful</h2></div><div class="card"><span class="tag">PROJECT IDEA</span><h3>${p.project}</h3><p>Make your learning tangible, one small improvement at a time.</p><button class="text-button" data-action="projects">Explore your project →</button></div></div></section></div>`;
if(page==='roadmap')html=title('Your next chapter starts here.',`${esc(state.path)} · ${esc(state.course)} · ${esc(state.year)}`)+`<div class="card"><span class="tag">INTRODUCTORY PREVIEW · EXPERT REVIEW PENDING</span><h2>${p.icon} ${state.path}</h2><p>This sample journey explains the direction. Only the first introductory mission is available. Completing it is a small learning milestone, not proof of professional readiness.</p>${p.steps.map((s,i)=>`<div class="milestone"><span class="node ${i===0?'current':''}">${i===0&&done()?'✓':i+1}</span><div><strong>${s}</strong><small>${i===0?'Read, practise, and explain your understanding':'Planned module · not yet available'}</small></div>${i===0?'<button data-action="lesson">Open mission →</button>':''}</div>`).join('')}<div class="below"><button class="secondary" data-action="preferences">Change my direction</button></div></div>`;
if(page==='explore')html=title('Find your kind of future.','Explore a direction. You can always change your mind.')+`<div class="wide-grid">${Object.entries(paths).map(([name,x])=>`<article class="card"><div class="path-symbol">${x.icon}</div><span class="tag">INTRO MISSION AVAILABLE</span><h3>${name}</h3><p>${x.desc}</p><button class="secondary" data-select="${name}">${name===state.path?'Your current path ✓':'Explore this path ↗'}</button></article>`).join('')}</div><p>AI/ML, cloud computing, mobile development and more specialisations are planned. These sample paths need subject expert review before student rollout.</p>`;
if(page==='projects')html=title('Learn it. Build it. Make it yours.','Your work tells the story of what you understand.')+`<div class="card"><span class="tag">${esc(state.path)}</span><h2>${p.project}</h2><p>Start with a small scope. Explain the problem, create your first version, test it, and record what you learned. Request teacher feedback before describing the work as reviewed.</p><button class="primary" id="add-project">Add to my workspace ↗</button></div><div class="below">${state.projects.length?state.projects.map(x=>`<div class="card project-card"><span class="project-icon">▧</span><div><h3>${esc(x.title)}</h3><p>${esc(x.path)} · In progress · Self-recorded</p></div></div>`).join(''):'<p>Your project workspace is ready for your first idea.</p>'}</div>`;
if(page==='opportunities')html=title('Prepare for your next opportunity.','Connect your learning with experiences that help you grow.')+`<div class="card"><span class="tag">PREPARATION CHECKLIST</span><h2>Your internship preparation</h2><p>Employers set their own requirements. Use this checklist to prepare, then check each original listing carefully.</p>${['Choose a target role and read its requirements','Build a relevant project you can explain','Get feedback from a teacher or mentor','Prepare an accurate resume and portfolio','Practise explaining your work and contributions'].map((x,i)=>`<label><input type="checkbox" class="prep-check" data-index="${i}" style="display:inline;width:auto;margin-right:10px" ${state['prep'+i]?'checked':''}>${x}</label>`).join('')}</div><div class="empty below"><h3>Verified opportunity listings are coming later.</h3><p>No live internships, events, or certification recommendations are connected yet. Listings will need original sources, eligibility, fees, deadlines, and a last-checked date.</p></div>`;
if(page==='resume')html=title('Your work. Your story.','Create an honest, editable draft based on your own experience.')+`<div class="columns"><form id="resume-form" class="card"><h3>Tell your story in your words</h3><label>Contact details<input name="contact" value="${esc(state.resume?.contact||'')}" placeholder="Email · city · portfolio URL"></label><label>Education<input name="education" value="${esc(state.resume?.education||state.course)}"></label><label>Skills you can demonstrate<input name="skills" value="${esc(state.resume?.skills||'')}" placeholder="Add only skills you can explain"></label><label>Project and your personal contribution<textarea name="project" placeholder="What did you build? What did you contribute?">${esc(state.resume?.project||'')}</textarea></label><label>Completed certifications<textarea name="certifications" placeholder="Name, issuer, completion date; leave blank if none">${esc(state.resume?.certifications||'')}</textarea></label><button class="primary">Update draft</button></form><div><p class="resume-intro">No achievements are added automatically. Review your details before exporting. Use “Save as PDF” in your browser’s print window.</p><button class="secondary" id="print">Print / Save as PDF ↗</button><article class="resume-preview"><h2>${esc(state.name)}</h2><p>${esc(state.resume?.contact||'Your contact details')}</p><h3>Education</h3><p>${esc(state.resume?.education||state.course)}</p><h3>Skills</h3><p>${esc(state.resume?.skills||'Add demonstrated skills')}</p><h3>Projects</h3><p>${esc(state.resume?.project||'Describe your own completed work')}</p>${state.resume?.certifications?'<h3>Certifications</h3><p>'+esc(state.resume.certifications)+'</p>':''}</article></div></div>`;
$('#content').innerHTML=html;$('#content').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('#content').querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.path=b.dataset.select;persist();go('roadmap');toast('Your direction is updated. Previous progress is saved.')} );$('#add-project')?.addEventListener('click',()=>{if(state.projects.some(x=>x.path===state.path))return toast('This project is already in your workspace.');state.projects.push({path:state.path,title:p.project});persist();render();toast('Project added. Start small and record your contribution.')});$('.prep-check')&&document.querySelectorAll('.prep-check').forEach(c=>c.onchange=()=>{state['prep'+c.dataset.index]=c.checked;persist()});$('#resume-form')?.addEventListener('submit',e=>{e.preventDefault();state.resume=Object.fromEntries(new FormData(e.target));persist();render();toast('Resume draft updated')});$('#print')?.addEventListener('click',()=>window.print())}
function action(a){if(a==='lesson')lesson();else if(a==='preferences')preferences();else go(a)}function preferences(){$('#student-name').value=state.name;$('#course').value=state.course;$('#year').value=state.year;$('#path').value=state.path;$('#language').value=state.language;$('#preferences').showModal()}function lesson(){const p=paths[state.path];$('#lesson').innerHTML=`<div class="eyebrow">MISSION 01 · ${esc(state.path.toUpperCase())}</div><h2>${p.skill}</h2><span class="tag">INTRODUCTORY LEARNING SAMPLE</span><p>${p.lesson}</p><h3>Try it yourself</h3><p>Describe one example of this concept in your own words. Your note stays on this device; it is not automatically graded.</p><textarea id="reflection" aria-label="Your practice reflection" placeholder="My example is…">${esc(state['reflection'+state.path]||'')}</textarea><h3>Check your understanding</h3><p>${p.question}</p>${p.answers.map((a,i)=>`<button class="answer" data-answer="${i}">${esc(a)}</button>`).join('')}<div id="feedback" role="status" hidden></div><div class="dialog-actions"><button class="secondary" id="close-lesson">Close mission</button></div>`;$('#lesson').showModal();$('#close-lesson').onclick=()=>$('#lesson').close();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const feedback=$('#feedback');feedback.hidden=false;const reflection=$('#reflection').value.trim();if(!reflection){feedback.textContent='First, write a practice example. You can revise it as you learn.';return}state['reflection'+state.path]=reflection;if(Number(b.dataset.answer)===p.correct){const was=done();state.completed[state.path]=true;persist();feedback.textContent='Correct. '+p.explain+' Your introductory check is complete. This sample does not assess full mastery.';if(!was)toast('First milestone completed · +50 XP');render()}else{persist();feedback.textContent='Try again. '+p.explain}})}
$('#path').innerHTML=Object.keys(paths).map(x=>`<option>${x}</option>`).join('');$('#languages').innerHTML=['Python','Java','C','C++','C#','JavaScript','TypeScript','Go','Rust','Ruby','PHP','Kotlin','Swift','Dart','R','Julia','MATLAB','Scala','Haskell','Elixir','Erlang','Clojure','F#','OCaml','Lua','Perl','Fortran','COBOL','Assembly','SQL','Bash','PowerShell','HTML / CSS','Other / Not sure'].map(x=>`<option value="${x}">`).join('');$('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#settings').onclick=preferences;$('#profile').onclick=preferences;$('#cancel').onclick=()=>$('#preferences').close();$('#pref-form').onsubmit=e=>{e.preventDefault();state.name=$('#student-name').value.trim()||'Student';state.course=$('#course').value;state.year=$('#year').value;state.path=$('#path').value;state.language=$('#language').value.trim();persist();$('#preferences').close();render();toast('Your journey is personalised')};render();
